    long subarrayXor(vector<int> &arr, int k) {
        // code here
        int n = arr.size();
        int cnt=0;
        unordered_map<int, int>mp;
        int xorr=0;

        for(int i=0; i<n; i++){
            xorr ^= arr[i];
            if(xorr == k) cnt++;
            if(mp.count(xorr^k)){
                cnt += mp[xorr^k];
            }

            mp[xorr]++;
        }
        return cnt;
    }
};

