class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        int n = nums.size();
        if(n == 0 || n == 1) return n;
        unordered_set<int>st;

        for(int i=0; i<n; i++) st.insert(nums[i]);

        int maxi = 1;
        for(int x: nums){
            if(st.find(x - 1) == st.end()){
                int cnt = 1;
                int val = x;
                while(st.find(val+1) != st.end()){
                    val++;
                    cnt++;
                }
                maxi = max(maxi, cnt);
            }
        }
        return maxi;
    }
};

