    int lowerBound(vector[int]& arr, int target) {
        int n = arr.size();
        int i = 0, j = n - 1;

        while (i <= j) {
            int mid = i + (j - i) / 2;
            if (arr[mid] >= target) {
                j = mid - 1;
            } else {
                i = mid + 1;
            }
        }
        return i;
    }
};

