        int n = arr.size();
        int sum = 0, cnt=1;
        for(int i=0; i<n; i++){
            if(arr[i] > pages) return false;
            if(sum + arr[i]> pages){
                cnt++;
                sum = arr[i];
            }else sum += arr[i];
        }
        if(cnt > stud) return false;
        return true;
    }
    int findPages(vector<int> &arr, int k) {
        // code here
        int n = arr.size();
        if(k > n) return -1;
        int i=*min_element(arr.begin(), arr.end()), 
            j=accumulate(arr.begin(), arr.end(), 0);

        while(i<=j){
            int mid = i+(j-i)/2;
            if(isAllocated(arr, mid, k)) j=mid-1;
            else i=mid+1;
        }
        return i;
    }
};

