class Solution {
public:
    string reverseWords(string s) {
        vector<string> words;
        int n = s.size();
        int i = 0;

        while (i < n) {
            while (i < n && s[i] == ' ') i++;
            if (i == n) break;

            int start = i;
            while (i < n && s[i] != ' ') i++;
            words.push_back(s.substr(start, i - start));
        }

        reverse(words.begin(), words.end());

        string ans;
        for (int j = 0; j < words.size(); j++) {
            if (j > 0) ans += ' ';
            ans += words[j];
        }

        return ans;
    }
};

