    int maxMeetings(int start[], int end[], int n) {
        struct meeting meet[n];
        for (int i = 0; i < n; i++) {
            meet[i].start = start[i], meet[i].end = end[i], meet[i].pos = i + 1;
        }
        
        sort(meet, meet + n, comp);
        
        int count = 1;
        int limit = meet[0].end;
        
        for (int i = 1; i < n; i++) {
            if (meet[i].start > limit) {
                limit = meet[i].end;
                count++;
            }
        }
        return count;
    }
};

