class Solution{
public:
    int pageFaults(int N, int C, int pages[]){
        vector<int> memory;
        int faults = 0;
        
        for (int i = 0; i < N; i++) {
            auto it = find(memory.begin(), memory.end(), pages[i]);
            
            if (it == memory.end()) {
                faults++;
                if (memory.size() == C) {
                    memory.erase(memory.begin());
                }
                memory.push_back(pages[i]);
            } else {
                memory.erase(it);
                memory.push_back(pages[i]);
            }
        }
        return faults;
    }
};

