            if (minHeap.size() > k) {
                minHeap.pop();
            }
        }
        
        vector<int> res;
        
        // Extract the top k elements from the heap
        while (!minHeap.empty()) {
            res.push_back(minHeap.top().second);
            minHeap.pop();
        }
        
        return res;
    }
};

