class MyQueue {
private:
    stack<int> input;
    stack<int> output;

public:
    MyQueue() {}
    
    void push(int x) {
        // Always push to the input stack
        input.push(x);
    }
    
    int pop() {
        // Ensure output stack has the reversed elements
        if (output.empty()) {
            while (!input.empty()) {
                output.push(input.top());
                input.pop();
            }
        }
        
        // Pop the top of output (which is the front of the queue)
        int val = output.top();
        output.pop();
        return val;
    }
    
    int peek() {
        // Same logic as pop, but just peek at the top
        if (output.empty()) {
            while (!input.empty()) {
                output.push(input.top());
                input.pop();
            }
        }
        
        return output.top();
    }
    
    bool empty() {
        return input.empty() && output.empty();
    }
};

