class Solution {
public:
    // Iterative Approach
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> ans;
        stack<TreeNode*> st;
        TreeNode* curr = root;
        
        while (curr != NULL || !st.empty()) {
            // Keep going left
            if (curr != NULL) {
                st.push(curr);
                curr = curr->left;
            } 
            // When we reach a null, process the top node and go right
            else {
                curr = st.top();
                st.pop();
                ans.push_back(curr->val);
                curr = curr->right;
            }
        }
        
        return ans;
    }
};

