class Solution {
public:
    typedef unsigned long long ll;
    int widthOfBinaryTree(TreeNode* root) {
        if(!root)   
            return 0;
        queue<pair<TreeNode*, ll>> q;
        q.push({root, 0});
        ll maxWidth = 0;
        
        while(!q.empty()) {
            int n = q.size();
            ll f = q.front().second;
            ll l = q.back().second;
            maxWidth = max(maxWidth, l-f+1);
            
            while(n--) {
                TreeNode* curr = q.front().first;
                ll d          = q.front().second;
                q.pop();
                if(curr->left) {
                    q.push({curr->left, 2*d+1});
                }
                if(curr->right) {
                    q.push({curr->right, 2*d+2});
                }
            }
        }
        return maxWidth;
    }
};

