class Solution {
private:
    Node* markParents(Node* root, unordered_map<Node*, Node*>& mpp, int target) {
        queue<Node*> q;
        q.push(root);
        Node* targetNode = NULL;
        
        while(!q.empty()) {
            Node* curr = q.front();
            q.pop();
            
            if(curr->data == target) targetNode = curr;
            
            if(curr->left) {
                mpp[curr->left] = curr;
                q.push(curr->left);
            }
            if(curr->right) {
                mpp[curr->right] = curr;
                q.push(curr->right);
            }
        }
        return targetNode;
    }

public:
    int minTime(Node* root, int target) {
        unordered_map<Node*, Node*> mpp;
        Node* targetNode = markParents(root, mpp, target);
        
        unordered_map<Node*, bool> visited;
        queue<Node*> q;
        
        q.push(targetNode);
        visited[targetNode] = true;
        int time = 0;
        
        while(!q.empty()) {
            int size = q.size();
            bool flag = false; // Check if any node burned in this second
            
            for(int i = 0; i < size; i++) {
                Node* curr = q.front();
                q.pop();
                
                // Fire spreads left
                if(curr->left && !visited[curr->left]) {
                    q.push(curr->left);
                    visited[curr->left] = true;
                    flag = true;
                }
                // Fire spreads right
                if(curr->right && !visited[curr->right]) {
                    q.push(curr->right);
                    visited[curr->right] = true;
                    flag = true;
                }
                // Fire spreads to parent
                if(mpp[curr] && !visited[mpp[curr]]) {
                    q.push(mpp[curr]);
                    visited[mpp[curr]] = true;
                    flag = true;
                }
            }
            
            if(flag == true) time++;
        }
        
        return time;
    }
};

