class Solution {
public:
    int findCeil(Node* root, int input) {
        int ceil = -1;
        
        while (root != NULL) {
            // Exact match found
            if (root->data == input) {
                ceil = root->data;
                return ceil;
            }
            
            // If current node is smaller, ceil must be on the right
            if (root->data < input) {
                root = root->right;
            } 
            // If current node is larger, it's a potential ceil, but look for a tighter one on the left
            else {
                ceil = root->data;
                root = root->left;
            }
        }
        
        return ceil;
    }
};

