public:
    void findPreSuc(Node* root, Node*& pre, Node*& suc, int key) {
        pre = NULL;
        suc = NULL;
        
        // Find Successor
        Node* curr = root;
        while (curr != NULL) {
            if (curr->key > key) {
                suc = curr;
                curr = curr->left; // Go left for tighter bound
            } else {
                curr = curr->right;
            }
