            for(int j = 0; j < V; j++)
                if(adj[i][j] == 1 && i != j) adjList[i].push_back(j);

        vector<bool> vis(V, false);
        int cnt = 0;
        for(int i = 0; i < V; i++) {
            if (!vis[i]) {
            bfs(i, adjList, vis);
            cnt++;
        }
        }
        return cnt;
    }
};

