// BFS (Kahn's Algorithm)
class Solution {
public:
    bool isCyclic(int V, vector<int> adj[]) {
        vector<int> indegree(V, 0);
        for (int i = 0; i < V; i++)
            for (auto it : adj[i]) indegree[it]++;

        queue<int> q;
        for (int i = 0; i < V; i++)
            if (indegree[i] == 0) q.push(i);

        int cnt = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            cnt++;
            for (auto it : adj[node]) {
                if (--indegree[it] == 0) q.push(it);
            }
        }
        return cnt != V;
    }
};

