class Solution {
public:
    int minimumMultiplications(vector<int>& arr, int start, int end) {
        if (start == end) return 0;
        const int MOD = 100000;
        vector<int> dist(MOD, -1);
        queue<int> q;

        dist[start] = 0;
        q.push(start);

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (int num : arr) {
                int next = (node * num) % MOD;
                if (dist[next] == -1) {
                    dist[next] = dist[node] + 1;
                    if (next == end) return dist[next];
                    q.push(next);
                }
            }
        }
        return -1;
    }
};

