class Solution {
    int timer = 1;

    void dfs(int u, int p, vector<vector<int>>& adj, vector<int>& vis, vector<int>& tin, vector<int>& low, vector<vector<int>>& ans) {
        vis[u] = 1;
        tin[u] = timer;
        low[u] = timer;
        timer++;

        for (auto v : adj[u]) {
            if (v == p) {
                continue;
            }

            if (!vis[v]) {
                dfs(v, u, adj, vis, tin, low, ans);
                low[u] = min(low[u], low[v]);

                if (low[v] > tin[u]) {
                    ans.push_back({u, v});
                }
            } else {
                low[u] = min(low[u], tin[v]);
            }
        }
    }

