class Solution {
    int timer = 1;

    void dfs(int u, int p, vector<int> adj[], vector<int>& vis, vector<int>& tin, vector<int>& low, vector<int>& mark) {
        vis[u] = 1;
        tin[u] = timer;
        low[u] = timer;
        timer++;

        int child = 0;

        for (auto v : adj[u]) {
            if (v == p) {
                continue;
            }

            if (!vis[v]) {
                dfs(v, u, adj, vis, tin, low, mark);
                low[u] = min(low[u], low[v]);

                if (low[v] >= tin[u] && p != -1) {
                    mark[u] = 1;
                }
                child++;
            } else {
                low[u] = min(low[u], tin[v]);
            }
        }

        if (p == -1 && child > 1) {
            mark[u] = 1;
        }
    }

public:
    vector<int> articulationPoints(int V, vector<int> adj[]) {
        vector<int> vis(V, 0);
        vector<int> tin(V);
        vector<int> low(V);
        vector<int> mark(V, 0);

        for (int i = 0; i < V; i++) {
            if (!vis[i]) {
                dfs(i, -1, adj, vis, tin, low, mark);
            }
        }

        vector<int> ans;
        for (int i = 0; i < V; i++) {
            if (mark[i] == 1) {
                ans.push_back(i);
            }
        }

        if (ans.empty()) {
            return {-1};
        }

        return ans;
    }
};

