class Solution {
    void dfs1(int u, vector<vector<int>>& adj, vector<int>& vis, stack<int>& st) {
        vis[u] = 1;

        for (auto v : adj[u]) {
            if (!vis[v]) {
                dfs1(v, adj, vis, st);
            }
        }
        st.push(u);
    }

    void dfs2(int u, vector<vector<int>>& revAdj, vector<int>& vis) {
        vis[u] = 1;

        for (auto v : revAdj[u]) {
            if (!vis[v]) {
                dfs2(v, revAdj, vis);
            }
        }
    }

public:
    int kosaraju(int V, vector<vector<int>>& adj) {
        vector<int> vis(V, 0);
        stack<int> st;

        for (int i = 0; i < V; i++) {
            if (!vis[i]) {
                dfs1(i, adj, vis, st);
            }
        }

        vector<vector<int>> revAdj(V);
        for (int i = 0; i < V; i++) {
            vis[i] = 0;
            for (auto v : adj[i]) {
                revAdj[v].push_back(i);
            }
        }

        int sccCount = 0;

        while (!st.empty()) {
            int u = st.top();
            st.pop();

            if (!vis[u]) {
                sccCount++;
                dfs2(u, revAdj, vis);
            }
        }

        return sccCount;
    }
};

